sys_script_include.script:
var FSMInstallBaseAJAX = Class.create();
FSMInstallBaseAJAX.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    INSTALL_BASE_ITEM_TABLE: 'sn_install_base_item',
    CUSTOMER_CONTACT_TABLE: 'customer_contact',

    getInstallBaseItemDetail: function() {
        var installBaseItemSysId = this.getParameter('sysparm_ibi_sys_id');
        if (!installBaseItemSysId) {
            return;
        }

        var response = {};
        var installBaseItemGR = FSMUtil.getRecord(this.INSTALL_BASE_ITEM_TABLE, installBaseItemSysId);
        if (!installBaseItemGR) {
            return;
        }

        var installBaseItemLocationSysId = (new FSMInstallBaseUtil()).getInstallBaseItemLocation(installBaseItemSysId);
        if (installBaseItemLocationSysId) {
            var location = FSMUtil.getRecord('cmn_location', installBaseItemLocationSysId);
            response['location'] = location.getDisplayValue();
            response['location_id'] = location.getValue('sys_id');
        }

        if (!installBaseItemGR.configuration_item.nil()) {
            var ci = FSMUtil.getRecord('cmdb_ci', installBaseItemGR.configuration_item);
            response['ci'] = ci.getDisplayValue();
            response['ci_id'] = ci.getValue('sys_id');
        }

        if (!installBaseItemGR.account.nil()) {
            response['account'] = installBaseItemGR.getDisplayValue('account');
            response['account_id'] = installBaseItemGR.getValue('account');
        }

        if (!installBaseItemGR.contact.nil()) {
            var contact = FSMUtil.getRecord(this.CUSTOMER_CONTACT_TABLE, installBaseItemGR.contact);
            response['contact'] = contact.getDisplayValue();
            response['contact_id'] = contact.getValue('sys_id');
        }

        if (!installBaseItemGR.consumer.nil()) {
            response['consumer'] = installBaseItemGR.getDisplayValue('consumer');
            response['consumer_id'] = installBaseItemGR.getValue('consumer');
        }

        return new JSON().encode(response);
    },

    type: 'FSMInstallBaseAJAX'
});
